Ext._define('media_indoor.content_list.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'media_indoor.content_list.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'search', '-', 'upPosition', 'downPosition', '->', 'download'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn'},
                    {header: 'Conteúdo', dataIndex: 'content_unicode', width: 120},
                    {header: 'Campanha', dataIndex: 'campaign_unicode', width: 120},
                    {header: 'Posição', dataIndex: 'position', width: 90},
                ]
            );

        return this._columnModel;
    },

    moveContent: function (direction) {
        var selected = this.getSelectionModel().getSelected()

        if (selected) {
            var rest = this.factoryRestful();
            var mask = new Ext.LoadMask(this.getEl(), { msg: 'Alterando posição...' });

            mask.show();
            rest.doRequest(
                rest.getRoute(
                    'move_content',
                    false,
                    'POST',
                    {
                        scope: this,
                        params: {
                            content_id: selected.get('pk'),
                            direction: direction
                        },
                        callback: function () {
                            mask.hide();
                            mask = null;
                        },
                        success: function (xhr) {
                            rst = Ext.decode(xhr.responseText);

                            if (rst.success) {
                                this.getStore().reload();
                            }
                            else {
                                Ext.Msg.show({
                                    title: 'Alterar posição',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: rst.message
                                });
                            }
                        },
                        failure: function () {
                            Ext.Msg.show({
                                title: 'Alterar posição',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: 'O sistema esta indisponível neste momento.'
                            });
                        }
                    })
            );

        } else {
            Ext.Msg.show({
                title: 'Modificar posição',
                msg: 'É necessário selecionar pelo menos um conteúdo para alterar a posição',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK
            });
        }
    },

    getUpPositionAction: function () {
        if (!this._upPositionAction)
            this._upPositionAction = Ext._create('Ext.Button', {
                text: 'Aumentar Posição',
                iconCls: 'icon-siatu icon-siatu-move-down',
                scope: this,
                handler: function () {
                    this.moveContent('up');
                }
            });

        return this._upPositionAction;
    },

    getDownPositionAction: function () {
        if (!this._downPositionAction)
            this._downPositionAction = Ext._create('Ext.Button', {
                text: 'Diminuir Posição',
                iconCls: 'icon-siatu icon-siatu-move-up',
                scope: this,
                handler: function () {
                    this.moveContent('down');
                }
            });

        return this._downPositionAction;
    }

});

core.RestfulGrid.register(
    'media_indoor.content_list.Restful',
    'media_indoor.content_list.Grid'
);

